// Extract question from webhook
const input = $input.first().json;
const question = input.body?.question || input.question || "";
const queryType = input.body?.queryType || input.queryType || "";

// Safety check
if (!question) {
  return [{
    json: {
      originalQuestion: "",
      normalizedQuestion: "",
      queryType: queryType,
      category: "general",
      dataType: "text",
      error: "No question provided"
    }
  }];
}

// Normalize question
const normalizedQuestion = question.toLowerCase().trim();

// Detect category based on keywords
let category = "general";
let dataType = "text";

if (normalizedQuestion.includes("population") || normalizedQuestion.includes("people")) {
  category = "population";
  dataType = "numeric";
} else if (normalizedQuestion.includes("area") || normalizedQuestion.includes("km") || normalizedQuestion.includes("square")) {
  category = "geographic";
  dataType = "numeric";
} else if (normalizedQuestion.includes("literacy") || normalizedQuestion.includes("education") || normalizedQuestion.includes("school")) {
  category = "education";
  dataType = "percentage";
} else if (normalizedQuestion.includes("hospital") || normalizedQuestion.includes("health") || normalizedQuestion.includes("medical")) {
  category = "health";
  dataType = "numeric";
} else if (normalizedQuestion.includes("income") || normalizedQuestion.includes("economic") || normalizedQuestion.includes("employment") || normalizedQuestion.includes("agriculture") || normalizedQuestion.includes("industry")) {
  category = "economic";
  dataType = "mixed";
} else if (normalizedQuestion.includes("urban") || normalizedQuestion.includes("household") || normalizedQuestion.includes("infrastructure")) {
  category = "urbanization";
  dataType = "percentage";
}

return [{
  json: {
    originalQuestion: question,
    normalizedQuestion,
    queryType,
    category,
    dataType
  }
}];

// Get all merged items
const items = $input.all();

console.log('Total merged items:', items.length);

// First item should have query data
const queryData = items[0].json;

if (!queryData || !queryData.normalizedQuestion) {
  return [{
    json: {
      matched: false,
      error: "No query data"
    }
  }];
}

const normalizedQuestion = queryData.normalizedQuestion.toLowerCase();
const category = queryData.category.toLowerCase();

console.log('Looking for:', normalizedQuestion);
console.log('In category:', category);

// Search through ALL items for best match
let bestMatch = null;
let bestScore = 0;

for (const item of items) {
  const data = item.json;

  // Skip if no database data
  if (!data.Statistic_Name) continue;

  let score = 0;

  // Category match (5 points)
  if (data.Category && data.Category.toLowerCase() === category) {
    score += 5;
  }

  // Keywords match (3 points each)
  if (data.Keywords) {
    const keywords = data.Keywords.toLowerCase().split(',').map(k => k.trim());
    for (const keyword of keywords) {
      if (normalizedQuestion.includes(keyword)) {
        score += 3;
      }
    }
  }

  // Question match (10 points)
  if (data.Question && normalizedQuestion.includes(data.Question.toLowerCase())) {
    score += 10;
  }

  // Statistic name match (8 points)
  if (data.Statistic_Name && normalizedQuestion.includes(data.Statistic_Name.toLowerCase())) {
    score += 8;
  }

  console.log(`Score for ${data.Statistic_Name}: ${score}`);

  if (score > bestScore) {
    bestScore = score;
    bestMatch = data;
  }
}

console.log('Best match:', bestMatch?.Statistic_Name, 'Score:', bestScore);

// Return result
if (bestMatch && bestScore > 3) {
  return [{
    json: {
      ...queryData,
      ...bestMatch,
      matched: true,
      matchScore: bestScore
    }
  }];
}

// No match
return [{
  json: {
    ...queryData,
    matched: false,
    matchScore: 0
  }
}];

// Format database answer with HTML
const data = $json;

console.log('Formatting data:', data);

// Build formatted answer with HTML
let formattedAnswer = `<b>${data.statisticName || data.Statistic_Name}:</b> ${data.value || data.Value}`;

// Add unit if exists
if (data.unit || data.Unit) {
  formattedAnswer += ` ${data.unit || data.Unit}`;
}

formattedAnswer += `<br><br>`;

// Add additional info if exists
if (data.additionalInfo || data.Additional_Info) {
  formattedAnswer += `<b>Details:</b><br>${data.additionalInfo || data.Additional_Info}<br><br>`;
}

// Add source and year
if (data.source || data.Source) {
  formattedAnswer += `<b>Source:</b> ${data.source || data.Source}`;
  if (data.year || data.Year) {
    formattedAnswer += ` (${data.year || data.Year})`;
  }
  formattedAnswer += `<br>`;
}

// Add category if exists
if (data.category || data.Category) {
  formattedAnswer += `<b>Category:</b> ${data.category || data.Category}`;
}

console.log('Formatted answer:', formattedAnswer);

return [{
  json: {
    question: data.originalQuestion,
    formattedAnswer: formattedAnswer,
    responseType: "DB_VALIDATED",
    category: data.category || data.Category,
    source: data.source || data.Source,
    year: data.year || data.Year
  }
}];

