// Format AI response
const data = $json;

// Extract AI response
let aiResponse = "";
if (data.choices && data.choices[0] && data.choices[0].message) {
  aiResponse = data.choices[0].message.content;
}

return [{
  json: {
    question: data.originalQuestion || "",
    formattedAnswer: aiResponse,
    responseType: "AI_GENERATED",
    disclaimer: "Data generated by AI. Please verify from official Census or government sources."
  }
}];

// Add this as a "Code" node between "HTML Extract" and "AI_Statistics_Generator1"
// Set the Code node to: Run once per item | JavaScript

const question = $input.first().json.body ? $input.first().json.body.message : $('Webhook').first().json.body.message;
const sourceLink = $('Google Search').first().json.organic_results[0].link;
const rawText = $('HTML Extract').first().json.text || '';

// Safely truncate and clean the text
const cleanText = rawText.substring(0, 8000);

// Build the payload as a JS object — n8n will serialize it correctly
const payload = {
  model: "llama-3.3-70b-versatile",
  temperature: 0.3,
  messages: [
    {
      role: "system",
      content: "You are an official district information assistant for Kurukshetra, Haryana (India). Use https://kurukshetra.gov.in as the ONLY authoritative source. When asked about population, area, demographics, or district-wide statistics, ALWAYS provide DISTRICT-LEVEL data (e.g., district population: 9,64,655; area: 1,530 sq km), not village/block-level data unless specifically asked about a particular village or area. Provide clear, concise, citizen-friendly answers. Include ONE relevant reference link from kurukshetra.gov.in. Do NOT mention the scraped content, context, or your reasoning process — just give direct answers. For emergencies, respond with contact information FIRST."
    },
    {
      role: "user",
      content: `User Question: ${question}\n\nContext from Website (${sourceLink}): ${cleanText}`
    }
  ]
};

return [{ json: payload }];

const data = $input.first().json;

if (!data.organic_results || data.organic_results.length === 0) {
  // No results from kurukshetra.gov.in - flag for AI fallback
  return [{
    json: {
      noResults: true,
      query: $('Webhook').first().json.body.message
    }
  }];
} else {
  // Results found - pass through normally
  return [{
    json: {
      link: data.organic_results[0].link,
      noResults: false
    }
  }];
}
